"""disaster_message_triage classifier. Generated by Foundry.

Self-contained: standard library only. No torch, no numpy.
"""

import array
import base64
import math
import sys
import zlib

FEATURE_DIM = 4096
HIDDEN_DIM = 128
NUM_CLASSES = 6
NGRAM_SIZES = (3, 4, 5)
LABELS = ["life_threatening_rescue", "medical_emergency", "hazard_report", "resource_need", "situational_update", "non_actionable"]


def _load(encoded):
    values = array.array("f")
    values.frombytes(base64.b64decode(encoded))
    if sys.byteorder != "little":
        values.byteswap()
    return values


# W1T is the first layer transposed to (FEATURE_DIM, HIDDEN_DIM) so that a
# sparse feature index selects one contiguous row.
_W1T = _load("")
_B1 = _load("")
_W2 = _load("")
_B2 = _load("HWT9vWZkaDz6Oci9CGlxvCPoNb3sFBs+")


def featurise(text):
    """Sparse (index, value) pairs. Must match foundry/featurise.py exactly."""
    cleaned = " ".join(text.lower().split())
    counts = {}
    for n in NGRAM_SIZES:
        for i in range(len(cleaned) - n + 1):
            index = zlib.crc32(cleaned[i:i + n].encode("utf-8")) % FEATURE_DIM
            counts[index] = counts.get(index, 0.0) + 1.0

    if not counts:
        raise ValueError(
            "no n-grams produced: text is shorter than %d characters after "
            "whitespace collapsing" % min(NGRAM_SIZES)
        )

    norm = math.sqrt(sum(v * v for v in counts.values()))
    if norm == 0.0:
        raise ValueError("zero-norm feature vector despite non-zero n-gram count")
    return [(index, value / norm) for index, value in counts.items()]


def logits(text):
    hidden = list(_B1)
    for index, value in featurise(text):
        offset = index * HIDDEN_DIM
        for j in range(HIDDEN_DIM):
            hidden[j] += value * _W1T[offset + j]

    for j in range(HIDDEN_DIM):
        if hidden[j] < 0.0:
            hidden[j] = 0.0

    out = []
    for k in range(NUM_CLASSES):
        offset = k * HIDDEN_DIM
        total = _B2[k]
        for j in range(HIDDEN_DIM):
            total += _W2[offset + j] * hidden[j]
        out.append(total)
    return out


def classify(text):
    scores = logits(text)
    best = 0
    for k in range(1, NUM_CLASSES):
        if scores[k] > scores[best]:
            best = k
    return LABELS[best]


if __name__ == "__main__":
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        print(classify(line))
